.overview-aside { display: flex; flex-direction: column; gap: 18px; position: sticky; top: 94px; }
.safety-panel .panel-body { padding-top: 12px; }
.safety-summary { display: flex; align-items: flex-start; gap: 10px; padding: 1px 0 11px; }
.safety-indicator { width: 9px; height: 9px; flex: 0 0 auto; margin-top: 4px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 9px color-mix(in srgb, var(--orange) 65%, transparent); }
.safety-indicator.disabled { background: var(--muted); box-shadow: none; }
.safety-summary strong, .safety-summary small { display: block; }
.safety-summary strong { font-size: 12px; }
.safety-summary small { margin-top: 3px; color: var(--muted); font-size: 10px; line-height: 1.4; }
.safety-rows { border-top: 1px solid var(--line); }
