.safety-row:last-child { border-bottom: 0; }
.safety-row .badge { flex: 0 0 auto; font-size: 8px; }
.safety-disclaimer { margin: 10px 0 0; padding: 9px 10px; border-left: 2px solid var(--orange); border-radius: 0 6px 6px 0; background: rgba(255,165,60,0.055); color: var(--muted); font-size: 10px; line-height: 1.5; }

